    (T, 'R 440 del', "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n", "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                ;\r\n"),
    (T, 'R 446 del', "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n        }\r\n        if (swapped)\r\n            return true;\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n", "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n        }\r\n        if (swapped)\r\n            return true;\r\n        ;\r\n"),
    (T, 'R 455 del', "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n        }\r\n        if (swapped)\r\n            return true;\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n    case SQUAD_ACTION_21: {\r\n        const bool a = TakeItems(m_action.target, ITEM_BEHAVIOUR_RESPAWNING);\r\n        const bool b = TakeItems(m_action.target, ITEM_BEHAVIOUR_KEY);\r\n        const bool c = TakeItems(m_action.target, ITEM_BEHAVIOUR_MISSION_EXPLOSIVE);\r\n        if (a || b || c)\r\n            return true;\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n", "bool C_SquadController::ExecuteAction(int timeDelta)\r\n{\r\n    if (m_ordersHeld)\r\n        return true;\r\n    if (m_action.delay != 0) {\r\n        m_action.delay -= timeDelta;\r\n        if (m_action.delay > 0)\r\n            return true;\r\n        if (m_action.delay < 0)\r\n            m_action.delay = 0;\r\n    }\r\n    if (m_action.finished) {\r\n        // Nothing to do: the cover's stance, and holding, the way the member holds.\r\n        if (m_coverStance != 0 && m_coverStance != (m_moveFlags & m_coverStance)) {\r\n            SetStance(static_cast<int>(m_coverStance));\r\n            m_coverStance = 0;\r\n        }\r\n        if (m_flags & FLAG_HOLDING) {\r\n            if (m_alertTime == 0 && m_eventTime == 0) {\r\n                m_facing->SetView(m_holdDir);\r\n                m_facing->SetFacing(m_holdDir);\r\n            }\r\n            return true;\r\n        }\r\n        return false;\r\n    }\r\n\r\n    // Attacks and following go on while the target lives.\r\n    bool attack = false;\r\n    bool vehicleAttack = false;\r\n    bool follow = false;\r\n    switch (m_action.type) {\r\n    case SQUAD_ACTION_ATTACK_VEHICLE:\r\n        vehicleAttack = true;\r\n        break;\r\n    case SQUAD_ACTION_ATTACK:\r\n    case SQUAD_ACTION_ATTACK_SILENTLY:\r\n        attack = true;\r\n        break;\r\n    case SQUAD_ACTION_FOLLOW:\r\n        follow = true;\r\n        break;\r\n    default:\r\n        break;\r\n    }\r\n\r\n    // 1. The walk to the place starts.\r\n    if (!m_action.started) {\r\n        if (!m_action.arrived) {\r\n            C_Actor *vehicle = m_human->m_vehicle;\r\n            if (vehicle) {\r\n                bool leave = false;\r\n                if (vehicle->GetType() == ACTOR_CAR) {\r\n                    if (m_human->m_seat != 0) {\r\n                        // A passenger at the seat's weapon attacks from there.\r\n                        if ((attack || vehicleAttack) && vehicle->HasSeatWeapon(m_human->m_seat))\r\n                            return true;\r\n                        leave = true;\r\n                    }\r\n                } else if (vehicle->GetType() == ACTOR_STATIC_WEAPON) {\r\n                    if (attack || vehicleAttack)\r\n                        return true;\r\n                    leave = true;\r\n                }\r\n                if (leave)\r\n                    C_HumanController::IssueCommand(MakeCommand(HUMAN_COMMAND_LEAVE_VEHICLE, 0, 0));\r\n            }\r\n            C_Actor *own = m_human->m_vehicle;\r\n            const bool driver = own && own->GetType() == ACTOR_CAR && m_human->m_seat == 0;\r\n            m_action.started = true;\r\n            if (driver) {\r\n                m_driver->SetVehicle(own);\r\n                m_driver->DriveTo(m_action.pos, 1.0f);\r\n                m_driver->SetPace(m_quiet ? MOVE_PACE_1 : MOVE_PACE_3);\r\n            } else {\r\n                LowerWeapon();\r\n                m_move->SetPos(m_action.pos);\r\n                m_flags &= ~FLAG_1;\r\n                // The direction kept is away from the place. (Its w: a stale local in the\r\n                // original.)\r\n                const S_vector4 &own4 = m_human->GetPosition4();\r\n                S_vector away(own4.x - m_action.pos.x, own4.y - m_action.pos.y, own4.z - m_action.pos.z);\r\n                away.Normalize();\r\n                m_holdDir.x = away.x;\r\n                m_holdDir.y = away.y;\r\n                m_holdDir.z = away.z;\r\n            }\r\n            SetStatusIcon(m_quiet ? 5 : 4);\r\n            return true;\r\n        }\r\n    } else if (!m_action.arrived) {\r\n        // 2. Walking (or driving): arrived at the target or within the radius.\r\n        C_Actor *own = m_human->m_vehicle;\r\n        if (!own || own->GetType() != ACTOR_CAR || m_human->m_seat != 0) {\r\n            const S_vector &pos = m_human->GetFrame()->GetWorldPos();\r\n            const float dx = m_action.pos.x - pos.x;\r\n            const float dy = m_action.pos.y - pos.y;\r\n            const float dz = m_action.pos.z - pos.z;\r\n            const float distance2 = dy * dy + dz * dz + dx * dx;\r\n            const float radius2 = m_action.radius * m_action.radius;\r\n            if ((m_action.target && IsAtTarget(m_action.target)) || distance2 < radius2) {\r\n                m_move->flags |= S_AIMoveOrder::FLAG_REROUTE;\r\n                m_action.arrived = true;\r\n            }\r\n            // About to pick up a body: stand up.\r\n            if (m_action.type == HUMAN_COMMAND_PICK_UP_BODY && distance2 < 16.0f && m_action.target\r\n                && m_action.target->GetType() == ACTOR_HUMAN) {\r\n                SetStance(MOVE_STANDING);\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n\r\n    // 3. Turned toward the target: the action's end.\r\n    if (m_action.turned) {\r\n        if (m_action.completed)\r\n            return true;\r\n        if (m_action.stance != 0) {\r\n            // (As the original: the stance is compared with the cover stance's flags.)\r\n            if (m_action.stance != (m_coverStance & m_moveFlags))\r\n                SetStance(static_cast<int>(m_action.stance));\r\n            m_action.stance = 0;\r\n        }\r\n        if (m_flags & FLAG_THROW)\r\n            m_flags &= ~FLAG_THROW;\r\n        if (m_flags & FLAG_LAUNCHER)\r\n            m_flags &= ~FLAG_LAUNCHER;\r\n        const bool goesOn = attack || vehicleAttack || follow;\r\n        if (goesOn) {\r\n            if (IsActorDead(m_action.target)) {\r\n                m_action.completed = true;\r\n                m_action.finished = true;\r\n            }\r\n        } else if (!m_action.keepGoing) {\r\n            m_action.finished = true;\r\n            m_action.completed = true;\r\n        } else {\r\n            m_action.completed = true;\r\n        }\r\n        if (m_action.type == SQUAD_ACTION_BOUND && m_boundHops != 0) {\r\n            // The next hop: a cover point 8 m on along the bound's direction (on the walking\r\n            // network, within its point's radius).\r\n            const S_vector4 from = WorldPos4Of(m_human->GetFrame());\r\n            S_vector4 ahead;\r\n            ahead.x = from.x + m_boundDir.x * 24.0f * 0.33333334f;\r\n            ahead.y = m_boundDir.y * 24.0f * 0.33333334f + from.y;\r\n            ahead.z = from.z + m_boundDir.z * 24.0f * 0.33333334f;\r\n            ahead.w = 0.0f;                             // (a stale local in the original)\r\n            S_vector4 hop = FindCoverPoint(ahead, m_boundDir, m_coverRadius, static_cast<uint32_t>(m_human->GetNetId()));\r\n            C_Checkpoints *network = GetGame()->GetCheckpoints();\r\n            const int point = network->FindNearest(XYZ(hop), 10.0f, -1.0f);\r\n            bool hopped = false;\r\n            if (point != CHECKPOINT_NONE) {\r\n                const S_Checkpoint *checkpoint = network->Get(point);\r\n                S_vector offset(hop.x - checkpoint->pos.x, 0.0f, hop.z - checkpoint->pos.z);\r\n                const float radius = static_cast<float>(checkpoint->radius) * 0.0625f;\r\n                // (The height of the hop is the offset's until it is the point's below.)\r\n                hop.y = 0.0f;\r\n                if (radius * radius < offset.z * offset.z + offset.x * offset.x) {\r\n                    offset.Normalize();\r\n                    hop.x = offset.x * radius + checkpoint->pos.x;\r\n                    hop.y = offset.y * radius;\r\n                    hop.z = offset.z * radius + checkpoint->pos.z;\r\n                }\r\n                // Far enough (2 m, in the xz plane) to be worth the hop.\r\n                const float ex = from.x - hop.x;\r\n                const float ey = -hop.y;\r\n                const float ez = from.z - hop.z;\r\n                hop.y = checkpoint->pos.y;\r\n                if (!(ez * ez + ey * ey + ex * ex < 4.0f)) {\r\n                    m_action.Set(nullptr, SQUAD_ACTION_BOUND, hop, m_action.dir, true, m_action.radius);\r\n                    // The members go one after another.\r\n                    const int alive = g_teamManager.GetPlayerTeam()->GetAliveCount();\r\n                    const int others = alive - 2;\r\n                    int delay = others == -1 ? 0 : (m_human->GetNetId() % (others + 1)) * 800;\r\n                    if (m_boundHops != 3)\r\n                        delay += others * 500;\r\n                    m_action.delay = delay;\r\n                    m_action.noCommand = true;\r\n                    --m_boundHops;\r\n                    if (delay != 0) {\r\n                        m_facing->SetView(m_boundDir);\r\n                        m_facing->SetFacing(m_boundDir);\r\n                        if (m_alertTime < delay)\r\n                            m_alertTime = delay;\r\n                        CoverStance(true);\r\n                        RaiseWeapon();\r\n                    }\r\n                    hopped = true;\r\n                }\r\n            }\r\n            if (!hopped)\r\n                m_boundHops = 0;\r\n        }\r\n        if (m_action.completed)\r\n            FinishAction(m_action.type);\r\n        return true;\r\n    }\r\n\r\n    // 4. Turning toward the target (or the direction).\r\n    S_vector dir;\r\n    if (m_action.useDir) {\r\n        dir.Set(m_action.dir.x, 0.0f, m_action.dir.z);\r\n        m_holdDir = m_action.dir;\r\n    } else if (m_action.target) {\r\n        const S_vector4 &to = m_action.target->GetPosition4();\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(to.x - own.x, 0.0f, to.z - own.z);\r\n    } else {\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        dir.Set(m_action.pos.x - own.x, 0.0f, m_action.pos.z - own.z);\r\n    }\r\n    dir.Normalize();\r\n    const S_vector4 dir4 = {dir.x, dir.y, dir.z, 0.0f};   // (w: a stale local in the original)\r\n    m_facing->SetView(dir4);\r\n    m_facing->SetFacing(dir4);\r\n    const S_vector4 frameDir = FrameDir4(m_human->GetFrame());\r\n    S_vector body(frameDir.x, 0.0f, frameDir.z);\r\n    body.Normalize();\r\n    const float dot = body.y * dir.y + dir.z * body.z + body.x * dir.x;\r\n    const bool climbing = m_human->m_body.GetClimbState() != 0 && !(m_move->flags & S_AIMoveOrder::FLAG_ROUTE);\r\n    if ((dot <= TURNED_COS || climbing) && !m_action.skipTurn)\r\n        return true;\r\n    m_action.turned = true;\r\n    m_action.delay = 1500;\r\n    if (m_flags & FLAG_LAUNCHER)\r\n        return true;\r\n    if (m_flags & FLAG_THROW) {\r\n        // A grenade at the place (not within 6 m).\r\n        const S_vector4 &own = m_human->GetPosition4();\r\n        const float dx = m_action.pos.x - own.x;\r\n        const float dy = m_action.pos.y - own.y;\r\n        const float dz = m_action.pos.z - own.z;\r\n        if (dx * dx + dy * dy + dz * dz <= 36.0f) {\r\n            m_action.completed = true;\r\n            SayReply(SENTENCE_CANNOT, true, 300, false);\r\n            return true;\r\n        }\r\n        m_fireOrder->SetThrow(m_action.pos);\r\n        m_action.delay = S_HumanBody::GetCarryAnimLength(ANIM_THROW, (~m_moveFlags >> 2) & 1, 0);\r\n        return true;\r\n    }\r\n\r\n    // 5. The command. A vehicle's seat: the asked one, else the highest free one.\r\n    int seat = 0;\r\n    C_Actor *target = m_action.target;\r\n    if (target\r\n        && (target->GetType() == ACTOR_CAR || target->GetType() == ACTOR_SUBMARINE || target->GetType() == ACTOR_STATIC_WEAPON)\r\n        && m_action.type == HUMAN_COMMAND_ENTER_VEHICLE) {\r\n        if (target->IsSeatBlocked(m_action.slot)) {\r\n            int count = target->GetSeatCount();\r\n            bool found = false;\r\n            while (count != 0) {\r\n                --count;\r\n                if (!target->IsSeatBlocked(count)) {\r\n                    found = true;\r\n                    break;\r\n                }\r\n            }\r\n            if (!found) {\r\n                m_action.keepGoing = false;\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n            seat = count;\r\n        } else {\r\n            seat = m_action.slot;\r\n        }\r\n    }\r\n    if (m_action.noCommand) {\r\n        // Only the walk: done (an order's walk of the module tells it).\r\n        if (m_action.type != SQUAD_ACTION_FOLLOW) {\r\n            m_action.delay = 0;\r\n            if (m_action.notifyModule) {\r\n                GetSquadCommander()->OnOrderMoveDone();\r\n                return true;\r\n            }\r\n        }\r\n        return true;\r\n    }\r\n    ShowActionIcon(m_action.type);\r\n    if (!IsActionNeeded()) {\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n\r\n    bool enterVehicle = false;\r\n    switch (m_action.type) {\r\n    case HUMAN_COMMAND_ENTER_VEHICLE:\r\n        enterVehicle = true;\r\n        break;\r\n    case HUMAN_COMMAND_PICK_UP_BODY:\r\n        if (target) {\r\n            if (target->GetType() == ACTOR_ITEM) {\r\n                m_human->RequestPickUpItem(target);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_SUPPLY_BOX) {\r\n                m_human->RequestTakeFromBox(target, m_action.slot);\r\n                return false;\r\n            }\r\n            if (target->GetType() == ACTOR_HUMAN && !(m_moveFlags & MOVE_STANDING)) {\r\n                SetStance(MOVE_STANDING);\r\n                m_action.delay = 1500;\r\n                PickUp(m_action.target, m_action.slot);\r\n                return true;\r\n            }\r\n        }\r\n        enterVehicle = true;\r\n        break;\r\n    case SQUAD_ACTION_SEARCH_BODY:\r\n        if (SearchBodyItems(static_cast<C_Human *>(m_action.target))) {\r\n            m_action.delay = 1000;\r\n            return true;\r\n        }\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    case SQUAD_ACTION_SWAP_UNIFORM: {\r\n        // The uniforms change hands, then the helmets.\r\n        C_Human *other = static_cast<C_Human *>(m_action.target);\r\n        C_Item *theirs = other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        C_Item *mine = m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem();\r\n        const bool swapped = m_human->RequestTransferItem(mine, ITEM_CONTAINER_UNIFORM, other, theirs, ITEM_CONTAINER_UNIFORM);\r\n        if (swapped) {\r\n            m_human->PutOnUniform(m_human->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n            other->PutOnUniform(other->GetContainer(ITEM_CONTAINER_UNIFORM)->GetItem()->GetUid());\r\n        }\r\n        C_Item *theirHead = other->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        C_Item *myHead = m_human->GetContainer(ITEM_CONTAINER_HEAD)->GetItem();\r\n        if (theirHead) {\r\n            const bool moved = myHead\r\n                                   ? m_human->RequestTransferItem(myHead, ITEM_CONTAINER_HEAD, other, theirHead, ITEM_CONTAINER_HEAD)\r\n                                   : m_human->RequestMoveItem(theirHead, other, ITEM_CONTAINER_HEAD, ITEM_CONTAINER_HEAD, 0);\r\n            if (!moved) {\r\n                SayReply(SENTENCE_CANNOT, true, 300, false);\r\n                return true;\r\n            }\r\n        }\r\n        if (swapped)\r\n            return true;\r\n        SayReply(SENTENCE_CANNOT, true, 300, false);\r\n        return true;\r\n    }\r\n    case SQUAD_ACTION_21: {\r\n        const bool a = TakeItems(m_action.target, ITEM_BEHAVIOUR_RESPAWNING);\r\n        const bool b = TakeItems(m_action.target, ITEM_BEHAVIOUR_KEY);\r\n        const bool c = TakeItems(m_action.target, ITEM_BEHAVIOUR_MISSION_EXPLOSIVE);\r\n        if (a || b || c)\r\n            return true;\r\n        ;\r\n"),
